</head>
<body>
  <div class="screen">
    <!-- Header -->
    <div class="header">
      <button class="nav-btn" id="prevMonth" aria-label="الشهر السابق">‹</button>
      <h1 id="monthYear">أكتوبر ٢٠٢٤</h1>
      <button class="nav-btn" id="nextMonth" aria-label="الشهر التالي">›</button>
    </div>

    <!-- Doctor info -->
    <div class="doctor-card">
      <div class="name">د. فاطمة المنصوري</div>
      <div class="specialty">أخصائية أطفال وتغذية</div>
    </div>

    <!-- Calendar -->
    <div class="calendar">
      <div class="weekdays">
        <span>س</span><span>ح</span><span>خ</span><span>ث</span><span>ر</span><span>ت</span><span>أ</span>
      </div>
      <div class="days" id="calendarDays"></div>
    </div>

    <!-- Time slots -->
    <div class="time-slots">
      <h2>اختر وقتًا</h2>
      <div class="slots-list" id="timeSlots"></div>
    </div>

    <!-- Confirm -->
    <button class="confirm-btn" id="confirmBtn" disabled>تأكيد الحجز</button>
  </div>

  <script>
    const monthYearEl = document.getElementById('monthYear');
    const calendarDaysEl = document.getElementById('calendarDays');
    const timeSlotsEl = document.getElementById('timeSlots');
    const confirmBtn = document.getElementById('confirmBtn');
    const prevBtn = document.getElementById('prevMonth');
    const nextBtn = document.getElementById('nextMonth');

    const arabicMonths = [
      'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
      'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
    ];

    const arabicWeekdaysShort = ['س', 'ح', 'خ', 'ث', 'ر', 'ت', 'أ'];

    let currentDate = new Date();
    let selectedDate = null;
    let selectedSlot = null;

    function renderCalendar(date) {
      const year = date.getFullYear();
      const month = date.getMonth();
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      monthYearEl.textContent = `${arabicMonths[month]} ${year}`;

      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      const daysInMonth = lastDay.getDate();

      // Shift so Saturday (6) is first day
      const startDay = (firstDay.getDay() + 1) % 7; // 0=Sat ... 6=Fri

      calendarDaysEl.innerHTML = '';

      // Previous month filler
      const prevMonthDays = new Date(year, month, 0).getDate();
      for (let i = 0; i < startDay; i++) {
        const dayEl = document.createElement('div');
        dayEl.classList.add('day', 'other-month');
        dayEl.textContent = prevMonthDays - startDay + i + 1;
        calendarDaysEl.appendChild(dayEl);
      }

      // Current month days
      for (let d = 1; d <= daysInMonth; d++) {
        const dayEl = document.createElement('div');
        dayEl.classList.add('day');
        dayEl.textContent = d;
        dayEl.dataset.date = `${year}-${month + 1}-${d}`;

        const thisDate = new Date(year, month, d);
        if (thisDate.getTime() === today.getTime()) {
          dayEl.classList.add('today');
        }

        if (selectedDate && thisDate.getTime() === selectedDate.getTime()) {
          dayEl.classList.add('selected');
        }

        dayEl.addEventListener('click', () => selectDate(thisDate));
        calendarDaysEl.appendChild(dayEl);
      }

      // Next month filler
      const totalCells = startDay + daysInMonth;
      const remaining = (7 - (totalCells % 7)) % 7;
      for (let j = 1; j <= remaining; j++) {
        const dayEl = document.createElement('div');
        dayEl.classList.add('day', 'other-month');
        dayEl.textContent = j;
        calendarDaysEl.appendChild(dayEl);
      }
    }

    function selectDate(date) {
      selectedDate = date;
      renderCalendar(currentDate);
      renderTimeSlots();
      updateConfirmButton();
    }

    function renderTimeSlots() {
      timeSlotsEl.innerHTML = '';
      const slots = [];
      for (let h = 9; h <= 11; h++) {
        for (let m = 0; m < 60; m += 30) {
          const displayHour = h < 10 ? '0' + h : h;
          const displayMin = m < 10 ? '0' + m : m;
          const timeStr = `${displayHour}:${displayMin}`;
          slots.push(timeStr);
        }
      }
      // Add 12:00
      slots.push('12:00');

      slots.forEach(slot => {
        const slotEl = document.createElement('div');
        slotEl.classList.add('slot');
        slotEl.textContent = slot;
        slotEl.dataset.slot = slot;

        if (selectedSlot === slot) {
          slotEl.classList.add('selected');
        }

        slotEl.addEventListener('click', () => selectSlot(slot));
        timeSlotsEl.appendChild(slotEl);
      });
    }

    function selectSlot(slot) {
      selectedSlot = slot;
      renderTimeSlots();
      updateConfirmButton();
    }

    function updateConfirmButton() {
      confirmBtn.disabled = !(selectedDate && selectedSlot);
    }

    prevBtn.addEventListener('click', () => {
      currentDate.setMonth(currentDate.getMonth() - 1);
      renderCalendar(currentDate);
    });

    nextBtn.addEventListener('click', () => {
      currentDate.setMonth(currentDate.getMonth() + 1);
      renderCalendar(currentDate);
    });

    confirmBtn.addEventListener('click', () => {
      if (selectedDate && selectedSlot) {
        alert(`تم حجز موعدك:\nالتاريخ: ${selectedDate.toLocaleDateString('ar-EG')}\nالوقت: ${selectedSlot}`);
      }
    });

    // Initial render
    renderCalendar(currentDate);
    renderTimeSlots();
  </script>
</body>
</html>
